		}
		return nil, fmt.Errorf("jsonfile: read notes file: %w", err)
	}

	if len(data) == 0 {
		return make(map[string]noteRecord), nil
	}

	var records []noteRecord
	if err := json.Unmarshal(data, &records); err != nil {
		return nil, fmt.Errorf("jsonfile: decode notes file: %w", err)
	}

	byID := make(map[string]noteRecord, len(records))
	for _, rec := range records {
		byID[rec.ID] = rec
	}
	return byID, nil
}

func (r *NoteRepository) save(byID map[string]noteRecord) error {
	records := make([]noteRecord, 0, len(byID))
	for _, rec := range byID {
		records = append(records, rec)
	}

	data, err := json.MarshalIndent(records, "", "  ")
	if err != nil {
		return fmt.Errorf("jsonfile: encode notes file: %w", err)
	}

	if err := os.WriteFile(r.path, data, 0o644); err != nil {
		return fmt.Errorf("jsonfile: write notes file: %w", err)
	}
	return nil
}

func (r *NoteRepository) Save(_ context.Context, note *domain.Note) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	byID, err := r.load()
	if err != nil {
