func TestCreateNote_Execute(t *testing.T) {
	fixedNow := time.Date(2024, 1, 2, 3, 4, 5, 0, time.UTC)
	errIDGeneration := errors.New("random source exhausted")

	tests := []struct {
		name        string
		input       CreateNoteInput
		idErr       error
		wantErr     error
		wantWrapped error
		wantTitle   string
		wantContent string
	}{
		{
			name:        "creates a note with valid input",
			input:       CreateNoteInput{Title: "Groceries", Content: "Milk, eggs"},
			wantTitle:   "Groceries",
			wantContent: "Milk, eggs",
		},
		{
			name:      "trims whitespace from the title",
			input:     CreateNoteInput{Title: "  Groceries  ", Content: ""},
			wantTitle: "Groceries",
		},
		{
			name:    "rejects an empty title",
			input:   CreateNoteInput{Title: "   ", Content: "irrelevant"},
			wantErr: domain.ErrEmptyTitle,
		},
		{
			name:        "propagates an ID generation failure",
			input:       CreateNoteInput{Title: "Groceries"},
			idErr:       errIDGeneration,
			wantWrapped: errIDGeneration,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			repo := newFakeNoteRepository()
			clock := fakeClock{now: fixedNow}
			ids := fakeIDGenerator{id: domain.NoteID("fixed-id"), err: tt.idErr}
			uc := NewCreateNote(repo, clock, ids)

			note, err := uc.Execute(context.Background(), tt.input)

			if tt.wantWrapped != nil {
				if !errors.Is(err, tt.wantWrapped) {
					t.Fatalf("Execute() error = %v, want wrapped %v", err, tt.wantWrapped)
				}
				return
			}

			if tt.wantErr != nil {
				if !errors.Is(err, tt.wantErr) {
					t.Fatalf("Execute() error = %v, want %v", err, tt.wantErr)
				}
				return
			}

			if err != nil {
				t.Fatalf("Execute() unexpected error: %v", err)
			}

			if note.Title != tt.wantTitle {
				t.Errorf("Title = %q, want %q", note.Title, tt.wantTitle)
			}
			if note.Content != tt.wantContent {
				t.Errorf("Content = %q, want %q", note.Content, tt.wantContent)
			}
			if !note.CreatedAt.Equal(fixedNow) {
				t.Errorf("CreatedAt = %v, want %v", note.CreatedAt, fixedNow)
			}
			if !note.UpdatedAt.Equal(fixedNow) {
				t.Errorf("UpdatedAt = %v, want %v", note.UpdatedAt, fixedNow)
			}

			stored, err := repo.FindByID(context.Background(), note.ID)
			if err != nil {
				t.Fatalf("expected note to be persisted, got error: %v", err)
			}
			if stored.Title != tt.wantTitle {
				t.Errorf("persisted Title = %q, want %q", stored.Title, tt.wantTitle)
			}
		})
	}
}

