func NewNoteStore(path string) (*NoteStore, error) {
	if dir := filepath.Dir(path); dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return nil, fmt.Errorf("jsonfile: create dir: %w", err)
		}
	}
	return &NoteStore{path: path}, nil
}

func (s *NoteStore) readAll() ([]noteRecord, error) {
	raw, err := os.ReadFile(s.path)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("jsonfile: read: %w", err)
	}

	var records []noteRecord
	if err := json.Unmarshal(raw, &records); err != nil {
		return nil, fmt.Errorf("jsonfile: decode: %w", err)
	}
	return records, nil
}

func (s *NoteStore) writeAll(records []noteRecord) error {
	raw, err := json.MarshalIndent(records, "", "  ")
	if err != nil {
		return fmt.Errorf("jsonfile: encode: %w", err)
	}
	if err := os.WriteFile(s.path, raw, 0o644); err != nil {
		return fmt.Errorf("jsonfile: write: %w", err)
	}
	return nil
}

func (s *NoteStore) Save(_ context.Context, note domain.Note) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	records, err := s.readAll()
	if err != nil {
		return err
	}
	replaced := false
	for i, record := range records {
		if record.ID == note.ID().String() {
			records[i] = newNoteRecord(note)
			replaced = true
			break
		}
	}
	if !replaced {
		records = append(records, newNoteRecord(note))
	}
	return s.writeAll(records)
}

func (s *NoteStore) List(_ context.Context) ([]domain.Note, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	records, err := s.readAll()
	if err != nil {
		return nil, err
	}
	notes := make([]domain.Note, 0, len(records))
	for _, record := range records {
		note, err := record.toDomain()
		if err != nil {
			return nil, fmt.Errorf("jsonfile: %w", err)
		}
		notes = append(notes, note)
	}
	return notes, nil
}

func (s *NoteStore) Delete(_ context.Context, id domain.NoteID) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	records, err := s.readAll()
	if err != nil {
		return err
	}
	kept := make([]noteRecord, 0, len(records))
	for _, record := range records {
		if record.ID != id.String() {
			kept = append(kept, record)
		}
	}
	return s.writeAll(kept)
}

