func checkLeaks(w io.Writer) int {
	profile := pprof.Lookup("goroutineleak")
	if profile == nil {
		return 0
	}
	if err := profile.WriteTo(w, 0); err != nil {
		log.Print(err)
		return 0
	}
	return profile.Count()
}

